import { materialsErg2024 } from "./erg2024";

// =============================================================================
// مرجع مواد خطرناک آتش‌نشانی — داده‌های مرجع واکنش اضطراری
// HAZMAT Emergency Response Reference Data
// منبع الگو: ERG (Emergency Response Guidebook), NFPA 704, GHS
// توجه: این داده‌ها برای آموزش و یادآوری سریع است. در حادثه واقعی همواره
// راهنمای رسمی ERG و دستورالعمل سازمان آتش‌نشانی خود را ملاحظه کنید.
// =============================================================================

export interface NFPA {
  health: number; // 0-4 آبی / Health
  flammability: number; // 0-4 قرمز / Flammability
  instability: number; // 0-4 زرد / Instability
  special?: string; // OX, SA, W, ★
}

export type GHSPictogram =
  | "flame"
  | "oxidizer"
  | "bomb"
  | "corrosion"
  | "gas"
  | "healthHazard"
  | "skull"
  | "exclamation"
  | "environment";

export interface Material {
  id: string;
  nameFa: string;
  nameEn: string;
  aliases?: string[];
  un: string;
  hazardClass: string;
  hazardClassName: string;
  guide: number;
  category?: string; // گروه‌بندی نمایشی (اگر نباشد از رده مشتق می‌شود)
  nfpa?: NFPA; // اختیاری — وقتی داده رسمی موجود است
  ghs?: GHSPictogram[];
  state: string;
  vapor?: string;
  flashPoint?: string;
  boilingPoint?: string;
  description?: string;
  health?: string;
  fire?: string;
  reactivity?: string;
  ppe?: "A" | "B" | "C" | "D";
  incompatibilities?: string[];
  firstAid?: string[];
  spill?: string;
  fireResponse?: string;
  isolation?: { small: string; large: string };
  protectiveAction?: { day: string; night: string; largeDay: string; largeNight: string };
}

