export function normalizeSearchText(value: string): string {
  return toLatinDigits(value)
    .normalize("NFKC")
    .replace(/[يى]/g, "ی")
    .replace(/ك/g, "ک")
    .replace(/[ۀة]/g, "ه")
    .replace(/[\u064B-\u065F\u0670]/g, "")
    .replace(/\u200c/g, " ")
    .toLowerCase()
    .replace(/\s+/g, " ")
    .trim();
}

export function materialSearchText(material: Material): string {
  return [
    material.id,
    material.un,
    material.nameFa,
    material.nameEn,
    material.hazardClass,
    material.hazardClassName,
    material.category,
    ...(material.aliases ?? []),
    ...(MATERIAL_ALIASES[material.id] ?? []),
    ...(ASSALOUYEH_MATERIAL_IDS.has(material.id) ? ["عسلویه", "پارس جنوبی", "South Pars", "PSEEZ"] : []),
  ]
    .filter(Boolean)
    .map((value) => normalizeSearchText(String(value)))
    .join(" ");
}

