// بررسی سلامت داده‌ها — شناسایی راهنمای گم‌شده، شناسه تکراری و UN نامعتبر
export interface IntegrityReport {
  orphanGuides: { id: string; name: string; guide: number }[];
  duplicateIds: string[];
  duplicateUns: string[];
  missingGuideForMaterial: { id: string; name: string; guide: number }[];
}

export function validateData(): IntegrityReport {
  const guideSet = new Set(Object.keys(ergGuides).map(Number));
  const seenIds = new Map<string, number>();
  const seenUns = new Map<string, number>();
  const missingGuideForMaterial: { id: string; name: string; guide: number }[] = [];

  for (const m of materials) {
    seenIds.set(m.id, (seenIds.get(m.id) ?? 0) + 1);
    if (m.un && m.un !== "—") seenUns.set(m.un, (seenUns.get(m.un) ?? 0) + 1);
    if (!guideSet.has(m.guide)) missingGuideForMaterial.push({ id: m.id, name: m.nameFa, guide: m.guide });
  }

  // راهنماهایی که هیچ ماده‌ای به آن‌ها ارجاع نمی‌دهد (اطلاعاتی، خطا نیست)
  const usedGuides = new Set(materials.map((m) => m.guide));
  const orphanGuides = Object.values(ergGuides)
    .filter((g) => !usedGuides.has(g.number))
    .map((g) => ({ id: String(g.number), name: g.title, guide: g.number }));

  const duplicateIds = [...seenIds.entries()].filter(([, c]) => c > 1).map(([k]) => k);
  const duplicateUns = [...seenUns.entries()].filter(([, c]) => c > 1).map(([k]) => k);

  return { orphanGuides, duplicateIds, duplicateUns, missingGuideForMaterial };
}

// تبدیل ارقام فارسی/عربی به لاتین برای جستجوی یکپارچه اعداد (مانند UN)
export function toLatinDigits(s: string): string {
  return s
    .replace(/[\u06F0-\u06F9]/g, (d) => String(d.charCodeAt(0) - 0x06f0))
    .replace(/[\u0660-\u0669]/g, (d) => String(d.charCodeAt(0) - 0x0660));
}

// استخراج دسته نمایشی (اگر نباشد از نام رده مشتق می‌شود)
export function categoryOf(m: Material): string {
  if (m.category) return m.category;
  const hc = m.hazardClassName || "";
  const cls = (m.hazardClass || "9").split(".")[0];
  if (cls === "2") {
    if (hc.includes("سمی")) return "گازهای سمی";
    if (hc.includes("قابل اشتعال")) return "گازهای قابل اشتعال";
    return "گازهای غیرقابل اشتعال";
  }
  if (cls === "3" || hc.includes("مایع قابل اشتعال") || hc.includes("مایع سمی")) return "مایعات قابل اشتعال";
  if (hc.includes("حلال")) return "حلال‌ها";
  if (hc.includes("خورنده")) return "مواد خورنده";
  if (hc.includes("سمی")) return "مواد سمی";
  if (hc.includes("اکسیدکننده") || cls === "5") return "اکسیدکننده‌ها";
  const map: Record<string, string> = {
    "1": "مواد منفجره",
    "4": "مواد واکنش‌پذیر",
    "7": "مواد رادیواکتیو",
    "9": "خطرات متفرقه",
  };
  return map[cls] ?? "خطرات متفرقه";
}

